// ---------------------------------------------------------------- procedural pixel art
function grid(w, h, ch) { const g = []; for (let y = 0; y < h; y++) g.push(new Array(w).fill(ch || '.')); return g; }
function gRect(g, x, y, w, h, ch) {
  for (let j = y; j < y + h; j++) for (let i = x; i < x + w; i++) if (g[j] && i >= 0 && i < g[j].length) g[j][i] = ch;
}
function gDisc(g, cx, cy, r, ch) {
  for (let j = Math.floor(cy - r); j <= cy + r; j++) for (let i = Math.floor(cx - r); i <= cx + r; i++) {
    if ((i - cx) * (i - cx) + (j - cy) * (j - cy) <= r * r && g[j] && i >= 0 && i < g[j].length) g[j][i] = ch;
  }
}
const gRows = (g) => g.map((r) => r.join(''));
function outline(g, ch) {
  const H = g.length, W = g[0].length, o = g.map((r) => r.slice());
  for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {
    if (g[y][x] !== '.') continue;
    const n = (yy, xx) => yy >= 0 && yy < H && xx >= 0 && xx < W && g[yy][xx] !== '.';
    if (n(y - 1, x) || n(y + 1, x) || n(y, x - 1) || n(y, x + 1)) o[y][x] = ch;
  }
  return o;
}
function artHill(w, h, c1, c2, c3) {
  const g = grid(w, h);
  const r = w / 2;
  for (let x = 0; x < w; x++) {
    const dx = (x + 0.5 - r) / r;
    const top = Math.round(h - Math.sqrt(Math.max(0, 1 - dx * dx)) * h);
    for (let y = top; y < h; y++) g[y][x] = c1;
    if (top < h) g[top][x] = c3;
  }
  for (let i = 0; i < 7; i++) {
    const px = Math.round(w * (0.25 + 0.5 * rnd())), py = Math.round(h * (0.35 + 0.5 * rnd()));
    if (g[py] && g[py][px] === c1) { gRect(g, px, py, 3, 2, c2); gRect(g, px + 1, py - 1, 1, 1, c2); }
  }
  return outline(g, 'k');
}
function artCloud(w, h, c1, c2, ol) {
  const g = grid(w, h);
  const n = Math.max(3, Math.round(w / 9));
  for (let i = 0; i < n; i++) {
    const cx = 6 + (w - 12) * (i / (n - 1)), r = h * (0.28 + 0.2 * Math.sin(i * 2.1 + 1) * Math.sin(i * 2.1 + 1));
    gDisc(g, cx, h - r - 2, r, c1);
  }
  gRect(g, 5, h - 6, w - 10, 4, c1);
  for (let x = 0; x < w; x++) for (let y = h - 1; y >= 0; y--) {
    if (g[y][x] === c1) { if (y >= h - 5) g[y][x] = c2; }
  }
  return ol ? outline(g, ol) : g;
}
function wrapDist(a, b, w) { const d = Math.abs(a - b) % w; return Math.min(d, w - d); }
function artMountains(w, h, c1, c2, snow) {
  const g = grid(w, h);
  const peaks = [[0.08, 0.35], [0.24, 0.08], [0.4, 0.4], [0.56, 0.18], [0.74, 0.02], [0.9, 0.3]];
  for (let x = 0; x < w; x++) {
    let top = h;
    for (const [px, py] of peaks) top = Math.min(top, Math.round(py * h + wrapDist(x, px * w, w) * 1.05));
    for (let y = Math.max(0, top); y < h; y++) g[y][x] = c1;
    if (snow && top < h * 0.3) for (let y = top; y < Math.min(h, top + 4 + (x % 3)); y++) g[y][x] = snow;
    const ridge = top + 10 + Math.round(Math.sin(x * 0.21) * 3);
    for (let y = Math.max(ridge, top + 1); y < h; y++) if ((x * 7 + y * 3) % 23 === 0) g[y][x] = c2;
  }
  return g;
}
function artRolling(w, h, c1, c2) {
  const g = grid(w, h), T = Math.PI * 2;
  for (let x = 0; x < w; x++) {
    const top = Math.round(h * 0.42 + Math.sin(T * 3 * x / w) * h * 0.2 + Math.sin(T * 7 * x / w + 1) * h * 0.08);
    for (let y = Math.max(0, top); y < h; y++) g[y][x] = y < top + 2 ? c2 : c1;
  }
  return g;
}
function artTreeLine(w, h, c1, c2) {
  const g = grid(w, h), n = Math.round(w / 11);
  for (let i = 0; i < n; i++) {
    const cx = (i + 0.5) * w / n, r = 6 + ((i * 7) % 5);
    for (const ox of [-w, 0, w]) {
      gDisc(g, cx + ox, h - 22 - r * 0.6, r, c1);
      gRect(g, Math.round(cx + ox) - 1, h - 24, 2, 24, c2);
    }
  }
  gRect(g, 0, h - 16, w, 16, c1);
  return g;
}
function artCaveWall(w, h, c1, c2) {
  const g = grid(w, h), T = Math.PI * 2;
  for (let x = 0; x < w; x++) {
    const top = Math.round(h * 0.2 + Math.sin(T * 3 * x / w) * h * 0.07 + Math.sin(T * 8 * x / w + 1) * h * 0.035);
    const bot = Math.round(h * 0.16 + Math.sin(T * 2 * x / w + 2) * h * 0.06 + Math.sin(T * 9 * x / w) * h * 0.02);
    for (let y = 0; y < top; y++) g[y][x] = c1;
    for (let y = h - bot; y < h; y++) g[y][x] = c2;
  }
  const n = 14;
  for (let i = 0; i < n; i++) {
    const x = Math.round((i + 0.5) * w / n), len = h * (0.28 + ((i * 5) % 4) * 0.06);
    for (let y = 0; y < len; y++) {
      const hw = Math.round((1 - y / len) * (4 + (i % 3)));
      gRect(g, x - hw, y, hw * 2 + 1, 1, c1);
    }
    const sx = Math.round(i * w / n + 9), sl = h * (0.14 + ((i * 3) % 4) * 0.04);
    for (let y = 0; y < sl; y++) {
      const hw = Math.round((y / sl) * (3 + (i % 2)));
      gRect(g, sx - hw, h - Math.round(sl) + y, hw * 2 + 1, 1, c2);
    }
  }
  return g;
}
function artHut() {
  const W = 72, H = 64, g = grid(W, H);
  // chimney
  gRect(g, 50, 4, 8, 18, 'k'); gRect(g, 51, 5, 6, 17, 'x'); gRect(g, 51, 5, 6, 2, 'z');
  // roof (stepped triangle)
  for (let y = 0; y < 26; y++) {
    const half = 4 + Math.round(y * 1.36);
    gRect(g, 36 - half, 6 + y, half * 2, 1, y % 4 === 3 ? 'r' : 'R');
    gRect(g, 36 - half - 1, 6 + y, 1, 1, 'k'); gRect(g, 36 + half, 6 + y, 1, 1, 'k');
  }
  gRect(g, 0, 32, W, 2, 'k');
  gRect(g, 1, 30, W - 2, 2, 'r');
  // log walls
  for (let y = 34; y < H - 1; y++) {
    gRect(g, 5, y, W - 10, 1, (y - 34) % 5 === 4 ? 'N' : ((y - 34) % 5 === 0 ? 'm' : 'M'));
  }
  gRect(g, 4, 34, 1, H - 35, 'k'); gRect(g, W - 5, 34, 1, H - 35, 'k');
  gRect(g, 4, H - 1, W - 8, 1, 'k');
  // door
  gRect(g, 29, 40, 14, 23, 'k'); gRect(g, 30, 41, 12, 22, 'N'); gRect(g, 31, 42, 10, 21, 'n');
  gRect(g, 38, 52, 2, 2, 'Y');
  // windows
  for (const wx of [11, 49]) {
    gRect(g, wx, 40, 12, 11, 'k'); gRect(g, wx + 1, 41, 10, 9, 'Y'); gRect(g, wx + 1, 41, 10, 2, 'y');
    gRect(g, wx + 5, 41, 2, 9, 'k'); gRect(g, wx + 1, 45, 10, 1, 'k');
  }
  // round attic window with paw emblem
  gDisc(g, 36, 22, 5, 'k'); gDisc(g, 36, 22, 4, 'Y'); gRect(g, 35, 22, 3, 3, 'A');
  gRect(g, 33, 19, 1, 2, 'A'); gRect(g, 36, 18, 1, 2, 'A'); gRect(g, 39, 19, 1, 2, 'A');
  return gRows(g);
}
function artLogo() { return null; }

function buildArt() {
  const head = rowsOf(FOX_HEAD);
  for (const k in FS_BODY) defSprite('fs_' + k, head.concat(rowsOf(FS_BODY[k])));
  for (const k in FB_BODY) defSprite('fb_' + k, head.concat(rowsOf(FB_BODY[k])));
  for (const k in ART) defSprite(k, rowsOf(ART[k]));
  defSprite('t_logTR', mirror(rowsOf(ART.t_logTL)).map((l) => l.replace(/i/g, 'Q').replace(/I/g, 'i').replace(/Q/g, 'I')));
  defSprite('t_logR', mirror(rowsOf(ART.t_logL)).map((l) => l.replace(/i/g, 'j')));
  defSprite('t_bushR', mirror(rowsOf(ART.t_bushL)));
  defSprite('t_cannonR', rowsOf(ART.t_cannon));
  const top = rowsOf(ART.t_top), dirt = rowsOf(ART.t_dirt);
  const edgeL = (rows, isTop) => rows.map((l, y) => (isTop && y < 1 ? '.' : (isTop && y < 5 ? '3' : '6')) + l.slice(1));
  const edgeR = (rows, isTop) => rows.map((l, y) => l.slice(0, 15) + (isTop && y < 1 ? '.' : (isTop && y < 5 ? '3' : '6')));
  defSprite('t_topL', edgeL(top, true)); defSprite('t_topR', edgeR(top, true));
  defSprite('t_topLR', edgeR(edgeL(top, true), true));
  defSprite('t_dirtL', edgeL(dirt)); defSprite('t_dirtR', edgeR(dirt)); defSprite('t_dirtLR', edgeR(edgeL(dirt)));
  const tree = rowsOf(ART.t_tree);
  defSprite('t_treeL', tree.map((l, y) => (y === 0 ? '.k' : y < 9 ? 'k' + l[1] : '..') + l.slice(2)).map((l, y) => (y === 0 ? '..' + l.slice(2) : l)));
  defSprite('t_treeR', tree.map((l, y) => l.slice(0, 14) + (y === 0 ? '..' : y < 9 ? l[14] + 'k' : '..')));
  defSprite('t_treeM', tree);
  for (const k in ICONS) defSprite('i_' + k, rowsOf(ICONS[k]));
  defSprite('hut', artHut());
  defSprite('flat_hh', rowsOf(ART.hh_walk1));
}

