const W0 = { lv: null, idx: 0, w: 0, t: null, bump: null, hidden: null, room: [0, 0], spawns: [], cannons: [], camX: 0, camXi: 0,
  shake: 0, shakeMag: 0, pole: null, door: 0, time: 0, hurry: false, cps: [] };
const COLS = 30;
const slots = [];
function tilesInit() {
  const root = $('tiles');
  for (let i = 0; i < COLS; i++) {
    const g = el('g', {}, root), uses = [];
    for (let r = 0; r < ROWS; r++) { const u = el('use', { y: r * TS, display: 'none' }, g); u._id = null; uses.push(u); }
    slots.push({ g, uses, col: -99 });
