// ---------------------------------------------------------------- level load
const ENT_CH = 'ahes1234j=|FKED@';
function loadLevel(idx, cpCol) {
  const lv = LEVELS[idx], meta = lv.meta;
  W0.lv = lv; W0.idx = idx; W0.w = lv.rows[0].length;
  const w = W0.w;
  W0.t = new Array(w * ROWS); W0.bump = new Uint8Array(w * ROWS);
  W0.spawns = []; W0.cannons = []; W0.cps = []; W0.pole = null; W0.multi = {};
  let start = [3, 12];
  for (let r = 0; r < ROWS; r++) {
    const row = lv.rows[r];
    for (let c = 0; c < w; c++) {
      let ch = row[c];
      if (ENT_CH.indexOf(ch) >= 0) {
        if (ch === '@') start = [c, r];
        else if (ch === 'E') { W0.pole = { c, r }; W0.t[r * w + c] = 'S'; continue; }
        else if (ch === 'D') W0.door = c;
        else if (ch === 'F' || ch === 'K') {
          if (G.diff === 0 || (G.diff === 1 && ch === 'F')) W0.cps.push({ c, r });
        } else {
          const hard = '1234'.indexOf(ch);
          if (hard >= 0) { if (G.diff === 2) W0.spawns.push({ ch: 'ahes'[hard], c, r, done: false }); }
          else W0.spawns.push({ ch, c, r, done: false });
        }
        ch = '.';
      }
      W0.t[r * w + c] = ch;
      if (ch === 'c' && (r === 0 || row[c] !== lv.rows[r - 1][c])) W0.cannons.push({ c, r, t: 1.5 + (c % 5) * 0.4 });
    }
  }
  W0.cps.sort((a, b) => a.c - b.c);
  W0.spawns.sort((a, b) => a.c - b.c);
  W0.spawnIdx = 0;
  const th = THEMES[meta.theme];
  $('sky').setAttribute('fill', th.sky);
  $('game').setAttribute('style', th.vars);
  document.documentElement.style.background = th.letter;
  for (const k in BG) show(BG[k].g, k === meta.theme);
  W0.room = meta.rooms[0];
  W0.time = [500, 400, 300][G.diff];
  W0.hurry = false;
  let sc = start[0], sr = start[1];
  if (cpCol !== undefined && cpCol !== null) {
    const cp = W0.cps.find((p) => p.c === cpCol);
    if (cp) { sc = cp.c; sr = cp.r; }
  }
  return { c: sc, r: sr };
}
function roomAt(px) {
  for (const rm of W0.lv.meta.rooms) if (px >= rm[0] * TS && px < (rm[1] + 1) * TS) return rm;
  return W0.lv.meta.rooms[0];
}
function camUpdate(snap) {
  const hx = HERO.x + HERO.w / 2;
  let cx = W0.camX;
  const L = 500, R = 620;
  if (hx - cx > R) cx = hx - R;
  if (hx - cx < L) cx = hx - L;
  if (snap) cx = hx - 560;
  const rm = W0.room;
  cx = clamp(cx, rm[0] * TS, Math.max(rm[0] * TS, (rm[1] + 1) * TS - VW));
  W0.camX = cx;
  W0.camXi = Math.round(cx);
}
function worldTransform(dt) {
  let sx = 0, sy = 0;
  if (W0.shake > 0) {
    W0.shake -= dt;
    const m = Math.ceil(W0.shakeMag * Math.min(1, W0.shake * 6));
    sx = Math.round((rnd() * 2 - 1) * m); sy = Math.round((rnd() * 2 - 1) * m);
  }
  $('world').setAttribute('transform', 'translate(' + (-W0.camXi + sx) + ',' + sy + ')');
  tilesUpdate(false);
  bgUpdate();
}
function shake(mag, t) { W0.shakeMag = Math.max(mag, W0.shake > 0 ? W0.shakeMag : 0); W0.shake = Math.max(W0.shake, t); }

// ================================================================ HERO (fox adventurer)
const PH = { walk: 290, run: 470, accW: 850, accR: 1150, fric: 1100, skid: 2600, air: 850,
  jump: 800, jumpRun: 0.17, gHold: 1600, gFall: 4400, maxFall: 1000, coyote: 0.09, buffer: 0.13 };
const HERO = { x: 0, y: 0, vx: 0, vy: 0, w: 30, h: 42, face: 1, ground: false, power: 0, inv: 0, crouch: false,
  coyote: 0, jbuf: 0, springT: 0, chain: 0, anim: 0, frame: 'fs_stand', growT: 0, growTo: 0, throwT: 0,
  dead: false, deadT: 0, plat: null, skid: false, airMax: 290, sq: 0, sqk: 0, prevBottom: 0, pole: null,
  warp: null, god: false, hideT: 0, kickImm: 0, lastSafe: null, dustT: 0 };
const IN = { l: 0, r: 0, u: 0, d: 0, run: 0, jumpP: 0, runP: 0 };
let heroSpr = null;

function heroInit() {
  const g = el('g', {}, $('heroL'));
  heroSpr = { g, u: el('use', { href: '#s_fs_stand' }, g), id: '', tr: '', vis: true };
}
function heroPlace(c, r) {
  const H = HERO;
  H.power = G.power;
  H.h = H.power ? 87 : 42; H.w = 30;
  H.x = c * TS + (TS - H.w) / 2; H.y = (r + 1) * TS - H.h;
  H.vx = 0; H.vy = 0; H.face = 1; H.ground = false; H.inv = 0; H.dead = false; H.growT = 0; H.pole = null;
  H.warp = null; H.plat = null; H.crouch = false; H.chain = 0; H.throwT = 0; H.springT = 0; H.hideT = 0; H.kickImm = 0;
  H.lastSafe = { x: H.x, y: H.y };
