  return (tFlag(c, r) & F_SOLID) !== 0;
}
function setHeroHeight(h) {
  const H = HERO;
  if (h === H.h) return true;
  if (h > H.h) {
    const top = H.y + H.h - h, r0 = Math.floor(top / TS), c0 = Math.floor(H.x / TS), c1 = Math.floor((H.x + H.w - 1) / TS);
    for (let c = c0; c <= c1; c++) if (heroSolid(c, r0)) return false;
  }
