}

function heroUpdate(dt) {
  const H = HERO;
  if (H.growT > 0) {
    H.growT -= dt;
    if (H.growT <= 0) { H.power = H.growTo; G.power = H.power; setHeroHeight(H.power ? 87 : 42); }
    return;
  }
  if (H.warp) { warpUpdate(dt); return; }
  if (H.inv > 0) H.inv -= dt;
  if (H.kickImm > 0) H.kickImm -= dt;
  if (H.throwT > 0) H.throwT -= dt;
  if (H.springT > 0) H.springT -= dt;
  if (IN.jumpP) H.jbuf = PH.buffer; else H.jbuf -= dt;
  const wantCrouch = H.power > 0 && H.ground && IN.d;
  if (wantCrouch && !H.crouch) { H.crouch = true; setHeroHeight(45); }
  else if (!wantCrouch && H.crouch && (H.ground || !IN.d)) { if (setHeroHeight(87)) H.crouch = false; }
  let dir = (IN.r ? 1 : 0) - (IN.l ? 1 : 0);
  if (H.crouch && H.ground) dir = 0;
  const maxV = IN.run ? PH.run : PH.walk;
  H.skid = false;
  if (H.ground) {
    if (dir) {
      if (H.vx * dir < 0) {
        H.vx += dir * PH.skid * dt; H.skid = Math.abs(H.vx) > 40;
        if (H.skid && (H.dustT -= dt) <= 0) { H.dustT = 0.06; fxPuff(H.x + H.w / 2 - dir * 10, H.y + H.h - 12, 'dust'); }
      } else H.vx += dir * (IN.run ? PH.accR : PH.accW) * dt;
      H.face = dir;
    } else H.vx = approach(H.vx, 0, (H.crouch ? 700 : PH.fric) * dt);
    if (Math.abs(H.vx) > maxV) H.vx = approach(H.vx, sgn(H.vx) * maxV, 900 * dt);
  } else {
    if (dir) { H.vx += dir * PH.air * dt; H.face = dir; }
    const am = Math.max(maxV, H.airMax);
    if (Math.abs(H.vx) > am) H.vx = sgn(H.vx) * am;
  }
  if (H.jbuf > 0 && (H.ground || H.coyote > 0)) {
    H.vy = -(PH.jump + Math.abs(H.vx) * PH.jumpRun);
    H.ground = false; H.coyote = 0; H.jbuf = 0; H.plat = null;
    H.airMax = Math.max(PH.walk, Math.abs(H.vx));
    H.sq = 0.1; H.sqk = -1;
    sfx('jump', H.power > 0);
  }
  if (H.power === 2 && IN.runP && G.state === 'playing') heroThrow();
  const g = H.vy < 0 && (IN.u || H.springT > 0) ? PH.gHold : PH.gFall;
  H.vy = Math.min(H.vy + g * dt, PH.maxFall);
  const wasGround = H.ground;
  heroMove(dt);
  if (wasGround && !H.ground && H.vy >= 0) H.coyote = PH.coyote; else if (!H.ground) H.coyote -= dt;
  if (!wasGround && H.ground) { H.sq = 0.1; H.sqk = 1; H.chain = 0; }
  if (H.ground && !H.plat) {
    const c = Math.floor((H.x + H.w / 2) / TS), r = Math.floor((H.y + H.h + 2) / TS);
    if (tFlag(c, r) & (F_SOLID | F_ONEWAY)) H.lastSafe = { x: c * TS + (TS - H.w) / 2, y: H.y };
  }
  if (H.sq > 0) H.sq -= dt;
  if (H.y > ROWS * TS + 40) {
    if (H.god || G.bot) heroRescue(); else heroDie(true);
  }
  // collect coins overlapped
  const c0 = Math.floor(H.x / TS), c1 = Math.floor((H.x + H.w - 1) / TS);
  const r0 = Math.floor(H.y / TS), r1 = Math.floor((H.y + H.h - 1) / TS);
  for (let c = c0; c <= c1; c++) for (let r = r0; r <= r1; r++) if (tAt(c, r) === 'o') { tSet(c, r, '.'); addCoin(); fxSparkle(c * TS + 24, r * TS + 24); }
  // warp logs
  if (IN.d && H.ground && !H.plat) {
    for (const wp of W0.lv.meta.warps) {
      const lx = wp[0] * TS + TS, top = wp[1] * TS;
      if (Math.abs(H.x + H.w / 2 - lx) < 18 && Math.abs(H.y + H.h - top) < 3) { warpStart(wp); break; }
    }
  }
}
function heroMove(dt) {
  const H = HERO;
  // horizontal
  H.x += H.vx * dt;
  const r0 = Math.floor(H.y / TS), r1 = Math.floor((H.y + H.h - 1) / TS);
  if (H.vx > 0) {
    const c = Math.floor((H.x + H.w) / TS);
