  } else if (H.vx < 0) {
    const c = Math.floor(H.x / TS);
    for (let r = r0; r <= r1; r++) if (heroSolid(c, r)) { H.x = (c + 1) * TS; H.vx = 0; break; }
  }
  // vertical
  const prevTop = H.y, prevBot = H.y + H.h;
