  if (H.deadT > 3.0) afterDeath();
}
function heroPower(kind, x, y) {
  const H = HERO;
  if (kind === 'berry') {
    popup(x, y, 1000); G.score += 1000;
    if (H.power === 0) { H.growT = 0.75; H.growTo = 1; sfx('power'); } else sfx('power');
  } else if (kind === 'leaf') {
