  }
}
function heroFrame() {
  const H = HERO;
  const big = H.power > 0;
  if (H.dead) return 'fs_die';
  if (H.growT > 0) {
    const ph = Math.floor(H.growT * 16) % 2;
    const from = H.growTo > H.power ? H.power : H.power, to = H.growTo;
    const showBig = ph ? (to > 0) : (from > 0);
    return showBig ? 'fb_stand' : 'fs_stand';
  }
  if (H.pole) return big ? 'fb_jump' : 'fs_pole';
  if (H.warp) return big ? 'fb_stand' : 'fs_stand';
  if (H.crouch) return 'fb_crouch';
