  const leafMode = power === 2 && (H.growT <= 0 || Math.floor(H.growT * 16) % 2);
  const palette = leafMode ? 'l' : 'n';
  if (palette !== s.pal) {
    s.pal = palette;
    s.u.setAttribute('style', leafMode ? '--sc1:#ffd23a;--sc2:#d07a00;--f1:#ff8a2a;--f3:#ffd08a' : '');
  }
  if (id !== s.id) { s.id = id; s.u.setAttribute('href', '#s_' + id); }
  const sp = SPR[id];
  let vis = true;
  if (H.inv > 0 && !H.dead && G.state === 'playing') vis = Math.floor(H.inv * 16) % 2 === 0;
  if (H.hideT > 0) vis = false;
  if (vis !== s.vis) { s.vis = vis; show(s.g, vis); }
