  if (H.sq > 0) { const k = H.sq / 0.1; if (H.sqk > 0) { sx = 1 + 0.12 * k; sy = 1 - 0.12 * k; } else { sx = 1 - 0.1 * k; sy = 1 + 0.1 * k; } }
  const flip = H.face < 0 ? -1 : 1;
  const tr = 'translate(' + cx + ',' + feet + ') scale(' + (sx * flip).toFixed(3) + ',' + sy.toFixed(3) + ') translate(-24,' + -sp.h + ')';
  if (tr !== s.tr) { s.tr = tr; s.g.setAttribute('transform', tr); }
}

// ---------------------------------------------------------------- warp logs
function warpStart(wp) {
  const H = HERO;
  H.warp = { wp, t: 0, phase: 0 };
  H.vx = 0; H.vy = 0; H.crouch = false; setHeroHeight(H.power ? 87 : 42);
  H.x = wp[0] * TS + TS - H.w / 2;
  $('under').appendChild(heroSpr.g);
