}
function warpUpdate(dt) {
  const H = HERO, w = H.warp;
  w.t += dt;
  if (w.phase === 0) {
    H.y += 110 * dt;
    if (w.t > 0.75) { w.phase = 1; w.t = 0; }
  } else if (w.phase === 1) {
    $('fade').setAttribute('opacity', Math.min(1, w.t / 0.25).toFixed(2));
