      case 'clover': id = 'clover'; ox = -6; oy = -12; break;
      case 'leaf': id = 'leaf'; ox = -6; oy = -8 + (e.st === 'move' ? Math.round(Math.sin(e.anim * 4) * 3) : 0); break;
      case 'dart': id = Math.floor(e.anim * 14) % 2 ? 'dart2' : 'dart1'; flip = e.vx < 0; ox = -15; oy = -15; break;
      case 'spring': id = e.st === 'fire' ? (e.t < 0.08 ? 'spring3' : e.t < 0.16 ? 'spring2' : 'spring1') : 'spring1'; ox = -3; oy = -12; break;
      case 'cp': id = e.st === 'on' ? (Math.floor(e.anim * 4) % 2 ? 'cp_on2' : 'cp_on1') : 'cp_off'; ox = -14; break;
      default: break;
    }
    if (e.st === 'ko') vflip = true;
    if (!id) { sprHide(s); continue; }
    sprSet(s, id, e.x + ox, e.y + oy, flip, vflip);
  }
  for (const p of PLATS) {
    if (!p.on) continue;
    const tr = 'translate(' + Math.round(p.x) + ',' + Math.round(p.y) + ')';
    if (tr !== p.tr) { p.tr = tr; p.g.setAttribute('transform', tr); }
  }
}

// ---------------------------------------------------------------- blocks
function hitBlock(c, r) {
  const ch = tAt(c, r), big = HERO.power > 0;
  bumpAbove(c, r);
  switch (ch) {
    case 'B':
      if (big) breakBrick(c, r); else { bumpAnim(c, r, 't_brick'); sfx('bump'); }
      break;
    case 'M': {
      const k = c + ',' + r;
      const m = W0.multi[k] || (W0.multi[k] = { n: 0, t0: G.clock });
      m.n++;
      coinPop(c, r);
      if (m.n >= 10 || G.clock - m.t0 > 4) { tSet(c, r, 'X'); bumpAnim(c, r, 't_used'); } else bumpAnim(c, r, 't_brick');
      break;
    }
    case 'C': case 'H': coinPop(c, r); tSet(c, r, 'X'); bumpAnim(c, r, 't_used'); break;
    case 'P': case 'Q': tSet(c, r, 'X'); bumpAnim(c, r, 't_used'); spawnItem(big ? 'leaf' : 'berry', c, r); sfx('appear'); break;
    case 'U': case 'L': tSet(c, r, 'X'); bumpAnim(c, r, 't_used'); spawnItem('clover', c, r); sfx('appear'); break;
    default: sfx('bump');
  }
}
function bumpAbove(c, r) {
  const top = r * TS;
  for (const e of ENTS) {
    if (!e.on || e.st === 'ko') continue;
    if (e.x + e.w < c * TS - 6 || e.x > (c + 1) * TS + 6) continue;
    if (Math.abs(e.y + e.h - top) > 8) continue;
    if (isEnemy(e) && e.type !== 'bee' && e.type !== 'pine') knockOut(e, e.x + e.w / 2 < c * TS + 24 ? -1 : 1, 100);
    else if (e.type === 'berry' || e.type === 'clover') { e.vy = -560; e.vx = e.x + e.w / 2 < c * TS + 24 ? -Math.abs(e.vx || 150) : Math.abs(e.vx || 150); }
  }
  if (tAt(c, r - 1) === 'o') { tSet(c, r - 1, '.'); coinPop(c, r); }
}
function breakBrick(c, r) {
  tSet(c, r, '.');
  const x = c * TS, y = r * TS;
  const v = [[-150, -720], [150, -720], [-110, -460], [110, -460]];
  v.forEach((vv, i) => {
    const f = fxSpawn('debris', x + (i % 2) * 24, y + (i < 2 ? 0 : 24));
    if (f) { f.vx = vv[0]; f.vy = vv[1]; f.g = 2400; f.life = 1.4; f.flip = i % 2 === 1; }
  });
  G.score += 50;
  sfx('break'); shake(3, 0.12);
}
function bumpAnim(c, r, sym) {
  const i = r * W0.w + c;
  W0.bump[i] = 1; refreshTile(c);
  const f = fxSpawn('bump', c * TS, r * TS);
  if (f) { f.sym = sym; f.c = c; f.r = r; f.life = 0.18; } else { W0.bump[i] = 0; refreshTile(c); }
}
function coinPop(c, r) {
  const f = fxSpawn('coin', c * TS, (r - 1) * TS);
  if (f) { f.vy = -960; f.g = 3000; f.life = 0.52; }
  addCoin(true);
}
function addCoin(silentFx) {
  G.coins++; G.score += 200;
  sfx('coin');
  if (G.coins >= 100) { G.coins -= 100; oneUp(HERO.x + HERO.w / 2, HERO.y - 10); }
}
function oneUp(x, y) { G.lives = Math.min(99, G.lives + 1); popup(x, y, '1UP'); sfx('oneup'); }

// ---------------------------------------------------------------- fx + popups
function fxSpawn(type, x, y) {
  for (const f of FXS) {
    if (f.on) continue;
    Object.assign(f, { on: true, type, x, y, vx: 0, vy: 0, g: 0, t: 0, life: 0.5, flip: false, sym: null, col: 0 });
    return f;
  }
  return null;
}
function fxPuff(x, y, kind) {
  const f = fxSpawn(kind, x - 9, y - 9);
  if (f) { f.life = kind === 'dust' ? 0.3 : 0.45; f.vy = kind === 'dust' ? -30 : -50; f.vx = (rnd() - 0.5) * 40; }
}
function fxSparkle(x, y) { const f = fxSpawn('spark', x - 7, y - 7); if (f) f.life = 0.35; }
function fxBurst(x, y, n, kinds) {
  for (let i = 0; i < n; i++) {
    const a = (i / n) * Math.PI * 2, sp = 180 + rnd() * 160;
    const f = fxSpawn('fw', x, y);
    if (!f) return;
    f.vx = Math.cos(a) * sp; f.vy = Math.sin(a) * sp - 60; f.g = 500; f.life = 0.8 + rnd() * 0.4;
    f.sym = (kinds || ['p_fw', 'p_fw2', 'p_fw3'])[i % 3];
  }
}
function fxUpdate(dt) {
  for (const f of FXS) {
    if (!f.on) continue;
    f.t += dt;
    if (f.t >= f.life) {
      if (f.type === 'bump') { W0.bump[f.r * W0.w + f.c] = 0; refreshTile(f.c); }
      if (f.type === 'coin') popup(f.x + 24, f.y, 200);
      f.on = false; sprHide(f.spr); continue;
    }
    f.vy += f.g * dt; f.x += f.vx * dt; f.y += f.vy * dt;
  }
  for (const p of POPS) {
    if (!p.on) continue;
    p.t += dt;
    if (p.t > 0.9) { p.on = false; sprHide(p.spr); }
  }
}
function fxRender() {
  for (const f of FXS) {
    if (!f.on) continue;
    const k = f.t / f.life;
    switch (f.type) {
      case 'debris': sprSet(f.spr, 'debris', f.x, f.y, f.flip, Math.floor(f.t * 10) % 2 === 1); break;
      case 'bump': { const off = Math.round(Math.sin(k * Math.PI) * 14); sprSet(f.spr, f.sym, f.x, f.y - off); break; }
      case 'coin': sprSet(f.spr, ['coin1', 'coin2', 'coin3', 'coin2'][Math.floor(f.t * 20) % 4], f.x, f.y); break;
      case 'dust': sprSet(f.spr, 'p_dust', f.x, f.y, false, false, ' scale(' + (1 + k).toFixed(2) + ')'); break;
      case 'smoke': sprSet(f.spr, 'p_smoke', f.x - 4, f.y - 4, false, false, ' scale(' + (1 + k * 0.8).toFixed(2) + ')'); break;
      case 'spark': sprSet(f.spr, 'p_spark', f.x, f.y, false, false, ' scale(' + (1.6 - k).toFixed(2) + ')'); break;
      case 'fw': sprSet(f.spr, f.sym, f.x, f.y, false, false, ' scale(' + (k > 0.7 ? 1 : 2) + ')'); break;
      case 'leafy': sprSet(f.spr, 'p_leaf', f.x, f.y, Math.floor(f.t * 3) % 2 === 1); break;
      default: break;
    }
  }
  for (const p of POPS) {
    if (!p.on) continue;
    const sp = SPR['pop' + p.v];
    sprSet(p.spr, 'pop' + p.v, p.x - sp.w / 2, p.y - 20 - Math.min(40, p.t * 90));
  }
}
function popup(x, y, v) {
  let best = POPS[0];
  for (const p of POPS) { if (!p.on) { best = p; break; } if (p.t > best.t) best = p; }
  Object.assign(best, { on: true, x, y, v: String(v), t: 0 });
}

// ================================================================ UI (HUD, screens, buttons, input)
const UI = {};
const INK = '#1c1024', CREAM = '#fff1d0', GOLD = '#ffd23a';
function panel(parent, x, y, w, h, fill, border, inner) {
  const g = el('g', {}, parent);
  el('path', { d: boxPath(x - 3, y - 3, w + 6, h + 6, 6), fill: border || INK }, g);
  el('path', { d: boxPath(x, y, w, h, 6), fill: fill || CREAM }, g);
  if (inner) el('path', { d: boxPath(x + 6, y + 6, w - 12, h - 12, 3), fill: 'none', stroke: inner, 'stroke-width': 3 }, g);
  return g;
}
function mkButton(parent, x, y, w, h, label, hint, onClick, color) {
  const g = el('g', { class: 'btn', transform: 'translate(' + x + ',' + y + ')' }, parent);
  const face = color || '#ffd23a';
  const ring = el('path', { d: boxPath(-9, -9, w + 18, h + 18, 9), fill: '#fffaf0', display: 'none' }, g);
  el('path', { d: boxPath(-3, -3, w + 6, h + 6, 6), fill: INK }, g);
  const f = el('path', { d: boxPath(0, 0, w, h, 6), fill: face }, g);
  el('rect', { x: 6, y: 3, width: w - 12, height: 3, fill: '#ffffff', opacity: 0.55 }, g);
  el('rect', { x: 6, y: h - 6, width: w - 12, height: 3, fill: INK, opacity: 0.25 }, g);
  const lab = mkText(g, w / 2, 0, label, { font: 'cjk', fpx: 16, px: 2, fill: INK, ol: null, anchor: 'middle' });
  let hl = null;
  if (hint) hl = mkText(g, w / 2, 0, hint, { px: 2, fill: INK, ol: null, anchor: 'middle' });
  const labH = lab.h, hintH = hl ? hl.h + 6 : 0, top = Math.round((h - labH - hintH) / 2);
  lab.move(w / 2, top);
  if (hl) hl.move(w / 2, top + labH + 6);
  g.addEventListener('pointerdown', (e) => { e.stopPropagation(); auInit(); window.focus(); sfx('select'); onClick(); });
  g.addEventListener('pointerenter', () => f.setAttribute('fill', lighten(face)));
  g.addEventListener('pointerleave', () => f.setAttribute('fill', face));
  return { g, ring, face: f, setSel(on) { ring.setAttribute('display', on ? 'inline' : 'none'); }, lab };
}
function lighten(hex) {
  const n = parseInt(hex.slice(1), 16), r = Math.min(255, (n >> 16) + 40), g = Math.min(255, ((n >> 8) & 255) + 40), b = Math.min(255, (n & 255) + 40);
  return '#' + ((1 << 24) + (r << 16) + (g << 8) + b).toString(16).slice(1);
}
function iconUse(parent, id, x, y, sc) {
  const u = el('use', { href: '#s_' + id, transform: 'translate(' + x + ',' + y + ')' + (sc ? ' scale(' + sc + ')' : '') }, parent);
  return u;
}

// ---------------------------------------------------------------- HUD
function hudBuild() {
  const g = $('hud');
  el('rect', { x: 0, y: 0, width: VW, height: 44, fill: INK, opacity: 0.28 }, g);
  const lab = (x, t) => mkText(g, x, 12, t, { px: 3, fill: '#fffaf0', ol: INK });
  lab(32, 'SCORE'); lab(446, 'WORLD'); lab(690, 'TIME');
  UI.hScore = mkText(g, 140, 12, '000000', { px: 3, fill: GOLD, ol: INK });
  iconUse(g, 'i_coin', 300, 11);
  UI.hCoins = mkText(g, 330, 12, 'x00', { px: 3, fill: '#fffaf0', ol: INK });
  UI.hWorld = mkText(g, 554, 12, '1-1', { px: 3, fill: GOLD, ol: INK });
  UI.hTime = mkText(g, 780, 12, '400', { px: 3, fill: GOLD, ol: INK });
  iconUse(g, 'i_foxhead', 890, 11);
  UI.hLives = mkText(g, 920, 12, 'x3', { px: 3, fill: '#fffaf0', ol: INK });
