  const pb = el('g', { class: 'btn', transform: 'translate(1150,4)' }, g);
  el('path', { d: boxPath(0, 0, 36, 36, 6), fill: INK, opacity: 0.6 }, pb);
  el('rect', { x: 11, y: 9, width: 5, height: 18, fill: '#fffaf0' }, pb); el('rect', { x: 20, y: 9, width: 5, height: 18, fill: '#fffaf0' }, pb);
  pb.addEventListener('pointerdown', (e) => { e.stopPropagation(); window.focus(); if (G.state === 'playing') pauseGame(); else if (G.state === 'paused') resumeGame(); });
  UI.pauseBtn = pb;
}
function muteBuild() {
  const mb = el('g', { class: 'btn', transform: 'translate(1196,4)' }, $('ui'));
  el('path', { d: boxPath(0, 0, 36, 36, 6), fill: INK, opacity: 0.6 }, mb);
  iconUse(mb, 'i_spk', 2, 3);
  UI.muteX = el('path', { d: 'M23 12h3v3h3v3h-3v3h3v3h-3v3h-3v-3h-3v3h-3v-3h3v-3h-3v-3h3v-3h-3v-3h3v3h3z', fill: '#ff6a6a' }, mb);
  UI.muteW = el('path', { d: 'M23 12h3v3h-3zM26 15h3v12h-3zM23 27h3v3h-3zM20 17h3v8h-3z', fill: '#fffaf0' }, mb);
  mb.addEventListener('pointerdown', (e) => { e.stopPropagation(); window.focus(); auInit(); toggleMute(); });
  UI.muteBtn = mb;
  muteIcon();
}
function toggleMute() { auMute(!AU.muted); muteIcon(); }
function muteIcon() { show(UI.muteX, AU.muted); show(UI.muteW, !AU.muted); }
function hudUpdate() {
  const pad = (n, k) => String(Math.max(0, Math.floor(n))).padStart(k, '0');
  UI.hScore.set(pad(G.score, 6));
  UI.hCoins.set('x' + pad(G.coins, 2));
  UI.hWorld.set(LEVELS[G.level].meta.id);
  const t = Math.max(0, W0.time);
  UI.hTime.set(pad(t, 3));
  UI.hTime.opt.fill = t <= 100 ? '#ff7a6a' : '#fffaf0';
  UI.hLives.set('x' + G.lives);
  const pw = HERO.power === 2;
  if (pw !== UI.hPowOn) { UI.hPowOn = pw; show(UI.hPow, pw); }
}

