  el('rect', { x: 0, y: 672, width: VW, height: 48, fill: INK, opacity: 0.66 }, g);
  mkText(g, 640, 680, TXT.hint, { font: 'cjk', fpx: 12, px: 2, fill: '#fffaf0', ol: null, anchor: 'middle' });
