  el('rect', { width: VW, height: VH, fill: INK, opacity: 0.72 }, g);
  panel(g, 100, 44, 1080, 632, CREAM, INK, '#d89050');
  mkText(g, 640, 64, TXT.helpTitle, { font: 'cjk', fpx: 20, weight: '900', px: 2, fill: '#ffd23a', ol: INK, olw: 1, sh: '#9a4a10', shx: 1, shy: 2, anchor: 'middle' });
  mkText(g, 640, 118, 'HOW TO PLAY', { px: 2, fill: '#9a4a10', ol: null, anchor: 'middle' });
  const dark = '#3a1a08';
  mkText(g, 150, 150, TXT.helpCtl + ' CONTROLS', { font: 'cjk', fpx: 14, px: 2, fill: '#c0501c', ol: null });
  const keys = [[['<', '>'], ['A', 'D'], TXT.hMove], [['SPACE'], ['W', 'K'], TXT.hJump], [['SHIFT'], ['J'], TXT.hRun], [['~'], ['S'], TXT.hDown], [['P'], ['H', 'M'], TXT.hPause]];
  keys.forEach(([k1, k2, desc], i) => {
    const y = 196 + i * 78;
    let x = 150;
    for (const k of k1.concat(k2)) {
      const w = k.length > 1 ? 18 + k.length * 12 : 36;
      el('path', { d: boxPath(x, y, w, 36, 3), fill: dark }, g);
      el('path', { d: boxPath(x + 3, y + 3, w - 6, 27, 3), fill: '#fffaf0' }, g);
      mkText(g, x + w / 2, y + 9, k, { px: 2, fill: dark, ol: null, anchor: 'middle' });
      x += w + 8;
    }
    mkText(g, 340, y + 6, desc, { font: 'cjk', fpx: 12, px: 2, fill: dark, ol: null });
  });
  el('rect', { x: 606, y: 150, width: 3, height: 450, fill: '#e8c898' }, g);
  mkText(g, 640, 150, TXT.helpRules + ' RULES', { font: 'cjk', fpx: 14, px: 2, fill: '#c0501c', ol: null });
  const rules = [['ac_walk', TXT.rAcorn], ['hh_walk1', TXT.rHog], ['bt_shell', TXT.rBeetle], ['bee1', TXT.rBee], ['pine', TXT.rPine],
    ['berry', TXT.rBerry], ['leaf', TXT.rLeaf], ['coin1', TXT.rCoin], ['t_block', TXT.rBlock], ['pennant', TXT.rFlag]];
  rules.forEach(([id, txt], i) => {
    const col = i < 5 ? 0 : 1, row = i % 5;
    const x = 636 + col * 262, y = 192 + row * 84;
    el('path', { d: boxPath(x, y, 58, 58, 6), fill: '#6cb8ff' }, g);
    iconUse(g, id, x + 5, y + 5, 1);
    const [name, desc] = txt.split('\uff1a');
    mkText(g, x + 68, y + 2, name, { font: 'cjk', fpx: 12, px: 2, fill: '#c0501c', ol: null });
    const tt = mkText(g, x + 68, y + 30, desc || '', { font: 'cjk', fpx: 11, px: 2, fill: dark, ol: null });
    if (tt.w > 186) tt.g.setAttribute('transform', tt.g.getAttribute('transform') + ' scale(' + (186 / tt.w).toFixed(3) + ',1)');
    if (id === 'hh_walk1') {
      el('path', { d: 'M' + (x + 8) + ' ' + (y + 8) + 'l42 42m0 -42l-42 42', stroke: '#ee3a3a', 'stroke-width': 6, 'stroke-linecap': 'square' }, g);
    }
  });
  mkText(g, 640, 632, TXT.helpClose, { font: 'cjk', fpx: 12, px: 2, fill: '#9a4a10', ol: null, anchor: 'middle' });
  g.addEventListener('pointerdown', (e) => { e.stopPropagation(); closeHelp(); });
}
function openHelp() {
  if (G.state !== 'title' && G.state !== 'paused') return;
  G.helpFrom = G.state; setState('help'); sfx('blip', 990);
}
function closeHelp() { if (G.state === 'help') { setState(G.helpFrom || 'title'); sfx('blip', 770); } }

