function introBuild() {
  const g = el('g', { display: 'none' }, $('ui'));
  UI.intro = g;
  UI.introBg = el('rect', { width: VW, height: VH, fill: INK }, g);
  UI.introWorld = mkText(g, 640, 220, 'WORLD 1-1', { px: 7, bold: true, fill: '#fffaf0', ol: null, anchor: 'middle' });
  UI.introName = mkText(g, 640, 300, TXT.lv[0], { font: 'cjk', fpx: 22, weight: '900', px: 3, fill: '#ffd23a', ol: '#5a2c10', olw: 1, anchor: 'middle' });
  UI.introHero = el('use', { href: '#s_fs_stand', x: 560, y: 420 }, g);
  UI.introLives = mkText(g, 640, 440, 'x 3', { px: 4, fill: '#fffaf0', ol: null });
  UI.introDiff = mkText(g, 640, 540, '', { font: 'cjk', fpx: 12, px: 2, fill: '#8a90aa', ol: null, anchor: 'middle' });
}
function introShow() {
  const m = LEVELS[G.level].meta;
  UI.introWorld.set('WORLD ' + m.id);
  UI.introName.set(TXT.lv[G.level] + '  ' + ['SUNNY MEADOW', 'GLOWCAVE', 'AUTUMN HEIGHTS'][G.level]);
  UI.introName.opt.font = 'cjk';
  UI.introLives.set('x ' + G.lives);
  UI.introDiff.set(TXT.diff[G.diff] + (G.cp !== null ? '  \u00b7  ' + TXT.checkpoint : ''));
  UI.introBg.setAttribute('opacity', 1);
}
function resultsBuild() {
  const g = el('g', { display: 'none' }, $('ui'));
  UI.res = g;
  UI.resDim = el('rect', { width: VW, height: VH, fill: INK, opacity: 0.66 }, g);
  panel(g, 330, 70, 620, 590, CREAM, INK, '#d89050');
  UI.resTitle = mkText(g, 640, 96, TXT.over, { font: 'cjk', fpx: 28, weight: '900', px: 3, fill: '#ff6a5a', ol: INK, olw: 1, sh: '#6a1a18', shx: 1, shy: 2, anchor: 'middle' });
  UI.resSub = mkText(g, 640, 200, 'GAME OVER', { px: 4, bold: true, fill: '#9a4a10', ol: null, anchor: 'middle' });
  UI.resRows = [];
  for (let i = 0; i < 5; i++) {
    const y = 254 + i * 50;
    el('rect', { x: 380, y: y + 38, width: 520, height: 3, fill: '#e8c898' }, g);
    UI.resRows.push({
      l: mkText(g, 386, y, '', { font: 'cjk', fpx: 13, px: 2, fill: '#3a1a08', ol: null }),
      v: mkText(g, 894, y + 6, '', { px: 3, fill: '#3a1a08', ol: null, anchor: 'end' }),
    });
  }
  UI.resNew = mkText(g, 640, 508, TXT.newBest + ' NEW BEST', { font: 'cjk', fpx: 16, weight: '900', px: 2, fill: '#ffd23a', ol: INK, olw: 1, anchor: 'middle' });
  UI.resBtns = [
    mkButton(g, 380, 568, 250, 58, TXT.retry, 'ENTER', () => { if (G.state === 'over' || G.state === 'allclear') startGame(G.diff, true); }, '#a4e85a'),
    mkButton(g, 650, 568, 250, 58, TXT.toTitle, 'ESC', () => toTitle(), '#ff8a6a'),
  ];
}
function resultsShow(win) {
  UI.resTitle.set(win ? TXT.clear : TXT.over);
  UI.resTitle.opt.fill = win ? '#ffd23a' : '#ff6a5a';
  UI.resTitle.str = null; UI.resTitle.set(win ? TXT.clear : TXT.over);
  UI.resSub.set(win ? 'ALL CLEAR' : 'GAME OVER');
  const pad = (n, k) => String(Math.floor(n)).padStart(k, '0');
  const rows = [[TXT.score + ' SCORE', pad(G.score, 6)], [TXT.coins + ' COINS', String(G.totalCoins)], [TXT.kills + ' ENEMIES', String(G.kills)],
    [TXT.reached + ' WORLD', LEVELS[G.level].meta.id], [TXT.best + ' BEST', pad(G.best, 6)]];
  rows.forEach((r, i) => { UI.resRows[i].l.set(r[0]); UI.resRows[i].v.set(r[1]); });
  show(UI.resNew.g, G.newBest);
}
function toastBuild() {
  UI.toast = el('g', { display: 'none' }, $('ui'));
  UI.toastT = 0;
  UI.toastCache = {};
}
function toast(msg, dur) {
  for (const k in UI.toastCache) show(UI.toastCache[k].g, false);
  if (!UI.toastCache[msg]) UI.toastCache[msg] = mkText(UI.toast, 640, 98, msg, { font: 'cjk', fpx: 18, weight: '900', px: 2, fill: '#ffd23a', ol: INK, olw: 1, sh: INK, shx: 1, shy: 2, anchor: 'middle' });
  show(UI.toastCache[msg].g, true);
  show(UI.toast, true);
  UI.toastT = dur || 1.5;
}
function clearBannerBuild() {
  const g = el('g', { display: 'none' }, $('ui'));
  UI.clear = g;
  panel(g, 390, 120, 500, 150, '#1c1024', '#ffd23a');
  mkText(g, 640, 134, TXT.lvClear + ' COURSE CLEAR', { font: 'cjk', fpx: 20, weight: '900', px: 2, fill: '#ffd23a', ol: null, anchor: 'middle' });
  UI.clearTime = mkText(g, 640, 200, '', { px: 3, fill: '#fffaf0', ol: null, anchor: 'middle' });
  UI.clearLab = mkText(g, 640, 236, TXT.timeBonus + '  x50', { font: 'cjk', fpx: 11, px: 2, fill: '#8fd8ff', ol: null, anchor: 'middle' });
}

// ---------------------------------------------------------------- overlays per state
function updateOverlays() {
  const s = G.state;
  show(UI.title, s === 'title' || (s === 'help' && G.helpFrom === 'title'));
  show(UI.help, s === 'help');
  show(UI.pause, s === 'paused');
  show(UI.intro, s === 'intro');
  show(UI.res, s === 'over' || s === 'allclear');
  show($('hud'), s !== 'title' && !(s === 'help' && G.helpFrom === 'title'));
  show(UI.clear, s === 'levelclear' && LC.phase >= 3);
  if (s !== 'playing' && s !== 'levelclear') show(UI.toast, false);
}

// ---------------------------------------------------------------- input
const KEYS = {};
const USED = new Set(['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'KeyA', 'KeyD', 'KeyW', 'KeyS', 'KeyK', 'KeyJ', 'Space',
  'ShiftLeft', 'ShiftRight', 'KeyP', 'KeyH', 'KeyM', 'Enter', 'Escape', 'Digit1', 'Digit2', 'Digit3', 'NumpadEnter']);
const JUMPK = ['ArrowUp', 'KeyW', 'Space', 'KeyK'], RUNK = ['ShiftLeft', 'ShiftRight', 'KeyJ'];
function inputInit() {
  window.addEventListener('keydown', (e) => {
    const c = e.code;
    if (USED.has(c)) e.preventDefault();
    auInit();
    if (e.repeat) return;
    KEYS[c] = true;
    if (JUMPK.indexOf(c) >= 0) G.jumpP = true;
    if (RUNK.indexOf(c) >= 0) G.runP = true;
    onKey(c);
  });
  window.addEventListener('keyup', (e) => { KEYS[e.code] = false; if (USED.has(e.code)) e.preventDefault(); });
  window.addEventListener('blur', () => { for (const k in KEYS) KEYS[k] = false; if (G.state === 'playing') pauseGame(); });
  document.addEventListener('visibilitychange', () => { if (document.hidden && G.state === 'playing') pauseGame(); });
  document.documentElement.addEventListener('pointerdown', () => { window.focus(); auInit(); });
}
function onKey(c) {
  const s = G.state;
  if (c === 'KeyM') { toggleMute(); return; }
  if (s === 'title') {
    if (c === 'ArrowLeft' || c === 'KeyA') setDiff((G.diff + 2) % 3);
    else if (c === 'ArrowRight' || c === 'KeyD') setDiff((G.diff + 1) % 3);
    else if (c === 'Digit1' || c === 'Digit2' || c === 'Digit3') setDiff(+c.slice(5) - 1);
    else if (c === 'Enter' || c === 'NumpadEnter' || c === 'Space') { sfx('select'); startGame(G.diff, true); }
    else if (c === 'KeyH') openHelp();
  } else if (s === 'help') {
    if (c === 'KeyH' || c === 'Escape' || c === 'Enter') closeHelp();
  } else if (s === 'playing') {
    if (c === 'KeyP' || c === 'Escape') pauseGame();
  } else if (s === 'paused') {
    if (c === 'KeyP' || c === 'Enter') resumeGame();
    else if (c === 'KeyH') openHelp();
    else if (c === 'Escape') toTitle();
  } else if (s === 'over' || s === 'allclear') {
    if (G.resT < 0.6) return;
    if (c === 'Enter' || c === 'NumpadEnter' || c === 'Space') startGame(G.diff, true);
    else if (c === 'Escape') toTitle();
  } else if (s === 'intro') {
    if (c === 'Enter') G.introT = Math.min(G.introT, 0.3);
  }
}
function readInput() {
  if (G.bot) { botInput(); G.jumpP = false; G.runP = false; return; }
  const k = KEYS;
  IN.l = k.ArrowLeft || k.KeyA ? 1 : 0;
  IN.r = k.ArrowRight || k.KeyD ? 1 : 0;
  IN.u = k.ArrowUp || k.KeyW || k.Space || k.KeyK ? 1 : 0;
  IN.d = k.ArrowDown || k.KeyS ? 1 : 0;
  IN.run = k.ShiftLeft || k.ShiftRight || k.KeyJ ? 1 : 0;
  IN.jumpP = G.jumpP ? 1 : 0; IN.runP = G.runP ? 1 : 0;
  G.jumpP = false; G.runP = false;
}

// ================================================================ GAME STATE + LOOP
const G = { state: 'title', diff: 1, score: 0, coins: 0, totalCoins: 0, lives: 3, power: 0, level: 0, cp: null, kills: 0,
  clock: 0, best: 0, newBest: false, bot: false, demo: true, godFlag: false, helpFrom: null, introT: 0, resT: 0,
  jumpP: false, runP: false, botHold: 0, botStuck: 0, botLastX: 0, timeAcc: 0, shineT: 0, shineI: 0 };
const LC = { phase: -1, t: 0 };
const GOAL = { g: null, flag: null, flagY: 0, hut: null, smokeT: 0 };
const BEST_KEY = 'opus_showcase_pixel-quest_best';
function loadBest() { try { return +(localStorage.getItem(BEST_KEY) || 0); } catch (e) { return 0; } }
function saveBest() {
  G.newBest = G.score > G.best && G.score > 0;
  if (G.newBest) { G.best = G.score; try { localStorage.setItem(BEST_KEY, String(G.best)); } catch (e) { /* ignore */ } }
}
function setState(s) {
  G.state = s;
  if (s === 'over' || s === 'allclear') G.resT = 0;
  updateOverlays();
}
function resetEnts() {
  for (const e of ENTS) entKill(e);
  for (const p of PLATS) { p.on = false; p.g.setAttribute('display', 'none'); }
  for (const f of FXS) { f.on = false; sprHide(f.spr); }
  for (const p of POPS) { p.on = false; sprHide(p.spr); }
  for (const e of ENTS) $('ents').appendChild(e.spr.g);
}
function buildGoal() {
  const d = $('deco');
  while (d.firstChild) d.removeChild(d.firstChild);
  GOAL.flag = null;
  if (W0.pole) {
    const P = W0.pole, px = P.c * TS + 21, top = (P.r - 9) * TS;
    el('rect', { x: px - 3, y: top, width: 12, height: P.r * TS - top, fill: INK }, d);
    el('rect', { x: px, y: top, width: 6, height: P.r * TS - top, fill: '#e8f0ff' }, d);
    el('rect', { x: px + 3, y: top, width: 3, height: P.r * TS - top, fill: '#9aa6c8' }, d);
    el('use', { href: '#s_knob', x: px - 9, y: top - 22 }, d);
    GOAL.flagY = top + 6;
    GOAL.flag = el('use', { href: '#s_pennant' }, d);
    GOAL.px = px;
  }
  if (W0.door) {
    const r = LEVELS[W0.idx].rows.findIndex((row) => row[W0.door] === 'D');
    GOAL.hut = el('use', { href: '#s_hut', x: W0.door * TS + 24 - 108, y: (r + 1) * TS - 192 }, d);
    GOAL.hutX = W0.door * TS + 24 - 108; GOAL.hutY = (r + 1) * TS - 192;
  }
}
function goalRender() {
  if (GOAL.flag) GOAL.flag.setAttribute('transform', 'translate(' + (GOAL.px + 3) + ',' + Math.round(GOAL.flagY) + ') scale(-1,1)');
}

// ---------------------------------------------------------------- flow
function beginLevel(idx) {
  G.level = idx;
  const p = loadLevel(idx, G.cp);
  resetEnts(); buildGoal();
  heroPlace(p.c, p.r);
  W0.camX = 0; camUpdate(true); tilesUpdate(true); worldTransform(0);
  G.introT = 2.3; G.timeAcc = 0; LC.phase = -1;
  introShow(); setState('intro');
  musicStop();
  hudUpdate();
}
function startGame(diff, withIntro) {
  G.diff = diff; G.score = 0; G.coins = 0; G.totalCoins = 0; G.lives = [5, 3, 3][diff]; G.power = 0; G.cp = null;
  G.kills = 0; G.newBest = false; G.demo = false; G.bot = false; HERO.god = G.godFlag;
  beginLevel(0);
  if (!withIntro) startPlay();
}
function startPlay() {
  setState('playing');
  musicPlay(LEVELS[G.level].meta.music);
  AU.tempo = W0.time <= 100 ? 1.35 : 1;
}
function pauseGame() { if (G.state !== 'playing') return; setState('paused'); sfx('pause'); musicStop(); }
function resumeGame() { if (G.state !== 'paused') return; setState('playing'); sfx('pause'); musicPlay(LEVELS[G.level].meta.music); AU.tempo = W0.hurry ? 1.35 : 1; }
function toTitle() { sfx('blip', 520); enterTitle(); }
function enterTitle() {
  G.demo = true; G.bot = true; HERO.god = true; G.level = 0; G.cp = null; G.power = 0; LC.phase = -1;
  const p = loadLevel(0, null);
  resetEnts(); buildGoal(); heroPlace(p.c, p.r);
  W0.camX = 0; camUpdate(true); tilesUpdate(true);
  UI.bestT.set('BEST ' + String(G.best).padStart(6, '0'));
  setState('title');
  musicPlay(0);
}
function afterDeath() {
  G.lives--;
  if (G.lives <= 0) gameOver(); else beginLevel(G.level);
}
function gameOver() { saveBest(); setState('over'); resultsShow(false); sfx('over'); }
function allClear() { saveBest(); setState('allclear'); resultsShow(true); sfx('win'); for (let i = 0; i < 3; i++) fxBurst(W0.camXi + 320 + i * 320, 200, 14); }

// ---------------------------------------------------------------- goal / level clear
function checkPole() {
  if (!W0.pole || HERO.dead || HERO.pole || HERO.warp) return;
  const px = GOAL.px, top = (W0.pole.r - 9) * TS;
  if (HERO.x + HERO.w >= px - 2 && HERO.x <= px + 8 && HERO.y + HERO.h > top - 24) {
    if (G.demo) { enterTitle(); return; }
    startLevelClear();
  }
}
function startLevelClear() {
  const H = HERO, base = W0.pole.r * TS;
  H.pole = true; H.vx = 0; H.vy = 0; H.x = GOAL.px - H.w + 5; H.face = 1;
  if (H.crouch) { H.crouch = false; setHeroHeight(87); }
  H.y = Math.max(H.y, (W0.pole.r - 9) * TS - H.h * 0.5);
  const hgt = base - (H.y + H.h);
  const pts = hgt > 7.4 * TS ? 5000 : hgt > 5.4 * TS ? 2000 : hgt > 3.4 * TS ? 800 : hgt > 1.4 * TS ? 400 : 100;
  G.score += pts; popup(GOAL.px + 40, H.y + 10, pts);
  musicStop(); sfx('flag');
  LC.phase = 0; LC.t = 0; LC.bonus = 0;
  setState('levelclear');
}
function lcUpdate(dt) {
  const H = HERO, base = W0.pole.r * TS;
  LC.t += dt;
  if (LC.phase === 0) {
    H.y = Math.min(H.y + 430 * dt, base - H.h);
    GOAL.flagY = Math.min(GOAL.flagY + 430 * dt, base - 42);
    if (H.y >= base - H.h && GOAL.flagY >= base - 42) { LC.phase = 1; LC.t = 0; H.x = GOAL.px + 3; H.face = -1; }
  } else if (LC.phase === 1) {
    if (LC.t > 0.4) { LC.phase = 2; LC.t = 0; H.pole = null; H.face = 1; sfx('clear'); }
  } else if (LC.phase === 2) {
    IN.l = 0; IN.r = 1; IN.u = 0; IN.d = 0; IN.run = 0; IN.jumpP = 0; IN.runP = 0;
    const n = Math.ceil(dt / (1 / 120));
    for (let i = 0; i < n; i++) heroUpdate(dt / n);
    camUpdate(false);
    if (H.x + H.w / 2 >= W0.door * TS + 24 || LC.t > 7) { H.hideT = 99; LC.phase = 3; LC.t = 0; updateOverlays(); }
  } else if (LC.phase === 3) {
    if (LC.t > 0.6) {
      if (W0.time > 0) {
        const n = Math.min(W0.time, Math.max(1, Math.round(dt * 140)));
        W0.time -= n; G.score += n * 50; LC.bonus += n * 50;
        if ((LC.tk = (LC.tk || 0) + 1) % 3 === 0) sfx('tick');
      } else { LC.phase = 4; LC.t = 0; }
    }
    UI.clearTime.set('TIME ' + String(Math.max(0, W0.time)).padStart(3, '0') + '   +' + LC.bonus);
  } else if (LC.phase === 4) {
    const bursts = [0.15, 0.6, 1.05];
    for (let i = 0; i < 3; i++) {
      if (LC.t >= bursts[i] && !(LC['b' + i])) {
        LC['b' + i] = true;
        fxBurst(GOAL.hutX + 40 + i * 70, GOAL.hutY - 60 - (i % 2) * 50, 12);
        sfx('firework');
      }
    }
    if (LC.t > 2.1) {
      LC.b0 = LC.b1 = LC.b2 = false; LC.phase = 5;
      if (G.level < LEVELS.length - 1) { G.cp = null; G.power = HERO.power; beginLevel(G.level + 1); } else allClear();
    }
  }
}

// ---------------------------------------------------------------- autopilot (title attract + testing)
function botInput() {
  const H = HERO;
  IN.l = 0; IN.r = 1; IN.run = 1; IN.d = 0; IN.runP = 0; IN.jumpP = 0;
  let jump = false;
  const r0 = Math.floor(H.y / TS), r1 = Math.floor((H.y + H.h - 1) / TS);
  const ac = Math.floor((H.x + H.w + 34) / TS);
  for (let r = r0; r <= r1; r++) if (heroSolid(ac, r)) jump = true;
  if (H.ground) {
    const fr = Math.floor((H.y + H.h + 2) / TS);
    for (const look of [26, 60]) {
      const c = Math.floor((H.x + H.w + look) / TS);
      let gap = true;
      for (let r = fr; r < ROWS; r++) if (tFlag(c, r) & (F_SOLID | F_ONEWAY)) { gap = false; break; }
      if (gap) { jump = true; break; }
    }
  }
  for (const e of ENTS) {
    if (!e.on || !isEnemy(e) || e.st === 'ko' || e.st === 'flat') continue;
    const dx = e.x - (H.x + H.w);
    if (dx > -20 && dx < 120 && Math.abs(e.y + e.h - (H.y + H.h)) < 90) jump = true;
  }
  for (const p of PLATS) {
    if (p.on && H.plat !== p && p.x > H.x && p.x - H.x < 170 && H.ground && p.y < H.y + H.h + 20) jump = true;
  }
  if (H.plat) {
    const edge = H.plat.x + H.plat.w - (H.x + H.w);
    IN.r = 1; if (edge > 30) jump = false;
  }
  if (jump && (H.ground || H.coyote > 0)) { IN.jumpP = 1; G.botHold = 0.42; }
  IN.u = G.botHold > 0 ? 1 : 0;
  if (Math.abs(H.x - G.botLastX) < 0.5 && !H.warp) G.botStuck += 1 / 60; else G.botStuck = 0;
  G.botLastX = H.x;
  if (G.botStuck > 0.35 && H.ground) { IN.jumpP = 1; G.botHold = 0.45; }
}

// ---------------------------------------------------------------- main loop
function stepWorld(dt) {
  const H = HERO;
  if (G.botHold > 0) G.botHold -= dt;
  if (H.growT > 0) { heroUpdate(dt); return; }
  for (const p of PLATS) if (p.on) platUpdate(p, dt);
  platCarry();
  heroUpdate(dt);
  if (G.state !== 'playing' && G.state !== 'title') return;
  entsUpdate(dt);
  cannonsUpdate(dt);
  spawnUpdate();
  fxUpdate(dt);
  checkPole();
  camUpdate(false);
  if (G.state === 'playing') {
    G.timeAcc += dt;
    while (G.timeAcc >= 0.4) {
      G.timeAcc -= 0.4;
      W0.time--;
      if (W0.time === 100 && !W0.hurry) { W0.hurry = true; sfx('hurry'); AU.tempo = 1.35; toast(TXT.hurry, 2); }
      if (W0.time <= 0) { W0.time = 0; if (!H.god) heroDie(false); else W0.time = 50; break; }
    }
  }
}
function ambient(dt) {
  const th = W0.lv.meta.theme;
  if (th === 'autumn' && rnd() < dt * 2.2) {
    const f = fxSpawn('leafy', W0.camXi + rnd() * VW, -10);
    if (f) { f.vx = -40 - rnd() * 40; f.vy = 70 + rnd() * 40; f.life = 6; }
  }
  if (GOAL.hut && (GOAL.smokeT -= dt) <= 0) {
    GOAL.smokeT = 0.5;
    if (Math.abs(GOAL.hutX - W0.camXi - 500) < 1000) fxPuff(GOAL.hutX + 162, GOAL.hutY + 8, 'smoke');
  }
}
function tick(dt, noRender) {
  G.clock += dt;
  auTick();
  const s = G.state;
  if (s === 'playing' || s === 'title') {
    readInput();
    const n = Math.max(1, Math.ceil(dt * 120 - 0.01)), h = dt / n;
    for (let i = 0; i < n; i++) {
      stepWorld(h);
      if (i === 0) { IN.jumpP = 0; IN.runP = 0; }
      if (G.state !== s) break;
    }
    ambient(dt);
  } else if (s === 'dying') { heroDeathUpdate(dt); fxUpdate(dt); }
  else if (s === 'levelclear') { lcUpdate(dt); fxUpdate(dt); ambient(dt); }
  else if (s === 'intro') {
    G.introT -= dt;
    if (G.introT < 0.35) UI.introBg.setAttribute('opacity', Math.max(0, G.introT / 0.35).toFixed(2));
    if (G.introT <= 0) startPlay();
  } else if (s === 'over' || s === 'allclear') {
    G.resT += dt; fxUpdate(dt);
    if (s === 'allclear' && rnd() < dt * 1.5) { fxBurst(W0.camXi + 200 + rnd() * 880, 120 + rnd() * 200, 12); }
  }
  if (UI.toastT > 0) { UI.toastT -= dt; if (UI.toastT <= 0) show(UI.toast, false); }
  if ((G.shineT -= dt) <= 0) {
    G.shineT = 0.14; G.shineI = (G.shineI + 1) % SHINE.length;
    const c = SHINE[G.shineI];
    $('tiles').setAttribute('style', '--sh1:' + c[0] + ';--sh2:' + c[1] + ';--sh3:' + c[2]);
  }
  if (!noRender) render(dt);
}
function render(dt) {
  worldTransform(dt);
  heroRender(); entsRender(); fxRender(); goalRender();
  if (G.state !== 'title') hudUpdate();
  if (G.state === 'title') {
    const bob = Math.round(Math.sin(G.clock * 2.2) * 2) * 3;
    if (bob !== UI.bob) { UI.bob = bob; UI.logo.g.setAttribute('transform', UI.logo.g.getAttribute('transform').replace(/,-?\d+\)$/, ',' + (34 + bob) + ')')); }
  }
  if (G.state === 'over' || G.state === 'allclear') show(UI.resNew.g, G.newBest && Math.floor(G.clock * 3) % 2 === 0);
}
let lastT = 0;
function frame(ts) {
  requestAnimationFrame(frame);
  const now = ts / 1000;
  let dt = lastT ? now - lastT : 1 / 60;
  lastT = now;
  if (dt <= 0) return;
  tick(Math.min(dt, 1 / 30));
}

// ---------------------------------------------------------------- test hooks
window.__GAME__ = {
  get state() { return G.state; },
  get score() { return G.score; },
  start(diff) { startGame(clamp(diff | 0, 0, 2), false); return G.state; },
  debug: {
    god(on) { G.godFlag = on !== false; HERO.god = G.godFlag; return G.godFlag; },
    bot(on) { G.bot = on !== false; return G.bot; },
    warp(level, col) {
      if (level !== G.level || G.state === 'title') {
        G.level = level; G.demo = false; HERO.god = G.godFlag;
        const p = loadLevel(level, null); resetEnts(); buildGoal(); heroPlace(p.c, p.r);
      }
      let r = 3;
      for (; r < ROWS; r++) if ((tFlag(col, r) & (F_SOLID | F_ONEWAY)) && !(tFlag(col, r - 1) & F_SOLID)) break;
      HERO.x = col * TS + 9; HERO.y = Math.min(r, ROWS) * TS - HERO.h; HERO.vx = 0; HERO.vy = 0;
      W0.room = roomAt(HERO.x);
      for (const s of W0.spawns) if (s.c < col - 2) s.done = true;
      camUpdate(true); tilesUpdate(true);
      if (G.state !== 'playing') { setState('playing'); musicPlay(LEVELS[level].meta.music); }
      return this.info();
    },
    place(c, r) {
      HERO.x = c * TS + 9; HERO.y = (r + 1) * TS - HERO.h; HERO.vx = 0; HERO.vy = 0; HERO.plat = null;
      W0.room = roomAt(HERO.x); camUpdate(true); tilesUpdate(true); return this.info();
    },
    power(p) { HERO.power = p; G.power = p; setHeroHeight(p ? 87 : 42); return p; },
    kill() { heroDie(false); return G.state; },
    hurt() { heroHurt(); return HERO.power; },
    win() {
      HERO.x = GOAL.px - HERO.w - 60; HERO.y = (W0.pole.r - 5) * TS; HERO.vx = 200; camUpdate(true);
      startLevelClear(); return G.state;
    },
    time(t) { W0.time = t; return t; },
    lives(n) { G.lives = n; return n; },
    coins(n) { G.coins = n; return n; },
    ff(sec) { const n = Math.round(sec * 60); for (let i = 0; i < n; i++) tick(1 / 60, true); render(0); return this.info(); },
    hit(c, r) { hitBlock(c, r); return tAt(c, r); },
    spawn(ch, c, r) { spawnFromMap({ ch, c, r }); return true; },
    press(k, on) { KEYS[k] = on !== false; if (on !== false) { if (JUMPK.indexOf(k) >= 0) G.jumpP = true; if (RUNK.indexOf(k) >= 0) G.runP = true; } return true; },
    info() {
      let n = 0; for (const e of ENTS) if (e.on) n++;
      return { state: G.state, level: G.level, col: Math.floor((HERO.x + HERO.w / 2) / TS), x: Math.round(HERO.x), y: Math.round(HERO.y),
        power: HERO.power, lives: G.lives, coins: G.coins, score: G.score, time: W0.time, ents: n, cam: W0.camXi, ground: HERO.ground,
        cp: G.cp, kills: G.kills, lc: LC.phase };
    },
    ents() { return ENTS.filter((e) => e.on).map((e) => e.type + ':' + e.st + '@' + Math.round(e.x / TS) + ',' + Math.round(e.y / TS)); },
  },
};

// ---------------------------------------------------------------- boot
function init() {
  buildArt(); bgBuild(); tilesInit(); entsInit(); heroInit();
  hudBuild(); titleBuild(); helpBuild(); pauseBuild(); introBuild(); resultsBuild(); clearBannerBuild(); toastBuild(); muteBuild();
  UI.help.setAttribute('style', '--sh1:#ffd23a;--sh2:#f0a820;--sh3:#a86400');
  inputInit();
  G.best = loadBest();
  enterTitle();
  render(0);
  requestAnimationFrame(frame);
}
init();
